import java.io.*;

public class Main {
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        int[][] a = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                a[i][j] = fs.nextInt();
            }
        }

        int cellCols = cols - 1;
        int[] heights = new int[cellCols];
        int[] stack = new int[cellCols + 1];
        long answer = 0;

        for (int i = 0; i < rows - 1; i++) {
            for (int j = 0; j < cellCols; j++) {
                long lhs = (long) a[i][j] + a[i + 1][j + 1];
                long rhs = (long) a[i][j + 1] + a[i + 1][j];
                heights[j] = lhs <= rhs ? heights[j] + 1 : 0;
            }

            int top = -1;
            for (int j = 0; j <= cellCols; j++) {
                int currentHeight = (j == cellCols) ? 0 : heights[j];

                while (top >= 0 && heights[stack[top]] >= currentHeight) {
                    int height = heights[stack[top--]];
                    int left = (top >= 0) ? stack[top] + 1 : 0;
                    int width = j - left;
                    if (height > 0) {
                        long area = (long) (height + 1) * (width + 1);
                        answer = Math.max(answer, area);
                    }
                }

                if (j < cellCols) {
                    stack[++top] = j;
                }
            }
        }

        System.out.println(answer);
    }
}
